namespace BlazorApp.Services;

public record EquipmentItem(int Id, string Name, string Location, DateOnly LastInspected);

public interface IEquipmentService
{
    Task<List<EquipmentItem>> GetEquipmentAsync();
}

public class EquipmentService : IEquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate network/database latency
        await Task.Delay(800);

        return new List<EquipmentItem>
        {
            new(1, "Forklift A",        "Warehouse 1",  new DateOnly(2026, 5, 12)),
            new(2, "Conveyor Belt B",   "Warehouse 2",  new DateOnly(2026, 4, 28)),
            new(3, "Hydraulic Press C", "Shop Floor",   new DateOnly(2026, 3, 15)),
            new(4, "CNC Mill D",        "Machine Room", new DateOnly(2026, 6, 1)),
            new(5, "Welding Rig E",     "Bay 3",        new DateOnly(2026, 2, 20)),
            new(6, "Crane F",           "Yard",         new DateOnly(2026, 1, 10)),
            new(7, "Compressor G",      "Utility Room", new DateOnly(2025, 12, 5)),
        };
    }
}

@page "/inventory"
@using BlazorApp.Services
@inject IEquipmentService EquipmentService
@attribute [StreamRendering]

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToString("yyyy-MM-dd")</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? items;

    protected override async Task OnInitializedAsync()
    {
        items = await EquipmentService.GetEquipmentAsync();
    }
}

